D=[
("panacea","GREEK ORIGIN",[("pan-","all","全部","a big circle around many things"),("akos","cure, remedy","治療","a medicine bottle with a red cross")],("a cure for all → a fix-everything remedy","萬靈丹；萬能解方"),"a cartoon salesman holds up one magic bottle labeled 'FIX ALL' while a broken bike, a wilted plant, and a sad robot line up hopefully.","One bottle claims to cure it all,","A panacea? Watch it fall."),
("ephemeral","GREEK ORIGIN",[("epi-","upon, for","在…之上","a hand resting on top of a box"),("hemera","day","一天","a sun rising and setting over one day")],("lasting only a day → very short-lived","短暫的；瞬息即逝的"),"a student holds a beautiful soap bubble that shimmers for a moment while a mayfly drifts past a calendar showing just one day.","Here today, then gone by night,","Ephemeral, a fleeting light."),
("onerous","LATIN ORIGIN",[("onus, oneris","burden, load","重擔","a huge heavy sack"),("-ous","full of","充滿…的","an overflowing basket")],("full of burden → heavy and hard to do","繁重的；費力的"),"a tired student drags a giant backpack stuffed with fifty textbooks up a long staircase, sweat drops flying.","Heavy load and endless chore,","Onerous work, and then some more."),
("laity","GREEK ORIGIN",[("laos","the people","民眾","a crowd of ordinary people"),("laikos","of the people","屬於民眾的","a group of friends holding hands")],("the ordinary people → non-clergy, non-experts","（相對於神職人員的）平信徒；外行人"),"in a museum, a guide in a lab coat explains a dinosaur skeleton to a curious crowd of everyday visitors holding snacks and cameras.","Not the experts, just the crowd,","The laity ask questions loud."),
("pungent","LATIN ORIGIN",[("pungere","to prick, pierce","刺","a sharp pin poking a balloon"),("-ent","doing","正在…的","an action arrow")],("pricking the nose → sharp, strong smell or taste","刺鼻的；辛辣的"),"a boy sniffs a bowl of stinky tofu and garlic; zig-zag smell lines like tiny pins poke his nose and his eyes water.","Sharp as a pin, it stings the nose,","Pungent smells where garlic grows."),
("prosaic","LATIN ORIGIN",[("prosa","straightforward speech, prose","直白的散文","a plain straight line of text"),("-ic","like","像…的","an equals sign")],("like plain prose → dull, ordinary, unimaginative","平淡無奇的；乏味的"),"a gray robot reads a plain grocery list in a flat voice while a colorful poet beside it sparkles with stars and rainbows.","Plain and gray with nothing new,","Prosaic words just will not do."),
("charlatan","ITALIAN ORIGIN",[("ciarlare","to chatter, prattle","閒扯","a mouth with many speech bubbles"),("-ano","person who","…的人","a person silhouette")],("a chatterer → someone who fakes skill","騙子；冒充內行的人"),"a fake 'doctor' with a paper crown talks nonstop selling colored-water 'genius juice' at a fair while a smart kid points at the label 'just water'.","Lots of talk but nothing true,","A charlatan will fool you through."),
("perfunctory","LATIN ORIGIN",[("per-","through","穿過","an arrow passing through a ring"),("fungi","to perform, do","執行","a hand checking a box")],("just getting through it → done without care","敷衍的；草率的"),"a bored boy sweeps dirt under the rug in two seconds, eyes on his phone, while the mess pokes out on every side.","Rushed right through without a care,","Perfunctory: the dust's still there."),
("morass","DUTCH ORIGIN",[("moeras","marsh, swamp","沼澤","a muddy swamp with reeds"),("maresc","marsh (Old French)","沼澤地","boots stuck in mud")],("a sticky swamp → a mess that is hard to escape","困境；泥淖"),"a cartoon student stuck knee-deep in a swamp of tangled homework papers and sticky notes, trying to pull one boot free.","Stuck in mud and can't get out,","A morass of mess and doubt."),
("sophistry","GREEK ORIGIN",[("sophos","wise, clever","聰明的","an owl with glasses"),("-istes / -ry","one who practices; the practice","從事者；行為","a juggler of words")],("clever-sounding talk → tricky, misleading reasoning","詭辯；似是而非的推論"),"a fox in a debate suit points at a chalkboard 'proving' 2 + 2 = 5 with twisty arrows while the audience scratches their heads.","Clever words that twist and bend,","Sophistry won't win the end."),
("prolific","LATIN ORIGIN",[("proles","offspring","後代","a family of baby chicks"),("facere","to make","製造","a hammer building")],("making many offspring → producing a lot","多產的；豐富的"),"a happy author at a desk with a stack of books taller than the ceiling, a printer shooting out page after page, and a tree loaded with apples outside.","Book after book, she makes so many,","Prolific writers—more than plenty."),
("mundane","LATIN ORIGIN",[("mundus","world","世界","a globe"),("-ane","belonging to","屬於…的","a tag with a string")],("of this ordinary world → everyday and dull","平凡的；世俗的"),"a student brushes teeth, ties shoes, and waits for the bus in three small panels, all in plain gray tones with a yawning clock.","Brush and bus and same routine,","Mundane days, the gray in-between."),
("myriad","GREEK ORIGIN",[("murioi","ten thousand, countless","一萬；無數","a sky full of countless stars"),("-ad","group of","…的一組","a big bundle")],("ten thousand → countless, too many to count","無數的；極多的"),"a kid on a hill at night tries to count stars with a clicker that shows 9,999 while the sky is packed with endless stars and fireflies.","Stars on stars I cannot count,","Myriad lights, a huge amount."),
("dissident","LATIN ORIGIN",[("dis-","apart","分開","two arrows pointing away"),("sedere","to sit","坐","a chair")],("sitting apart → one who openly disagrees","異議分子；持不同政見者"),"in a classroom vote, all students sit together raising blue cards, while one student sits on a chair apart holding up a red card with a calm, brave face.","Sitting apart, she will not bend,","A dissident to the very end."),
("laudable","LATIN ORIGIN",[("laus, laudare","praise; to praise","讚美","clapping hands"),("-able","able to be","可以被…的","a check mark")],("able to be praised → deserving praise","值得稱讚的；可嘉的"),"a boy helps an elderly neighbor carry groceries while classmates clap and a gold star floats above him.","Kind deeds earn a loud applause,","Laudable for a worthy cause."),
("inimitable","LATIN ORIGIN",[("in-","not","不","a red no-sign"),("imitari","to imitate, copy","模仿","a photocopier")],("cannot be copied → uniquely excellent","無法模仿的；獨一無二的"),"a girl does a dazzling dance move on stage while three copy-robots try to follow and tangle themselves up; the photocopier jams.","No one else can do it quite,","Inimitable, shining bright."),
("jaded","ENGLISH ORIGIN",[("jade","worn-out old horse","疲憊的老馬","a tired droopy horse"),("-ed","made into","變成…的","a before-to-after arrow")],("worn out like an old horse → bored and tired of it","厭倦的；麻木的"),"a teen sits on a couch surrounded by toys and gadgets, yawning at yet another new game, next to a sleepy, droopy cartoon horse.","Seen it all, now bored and tired,","Jaded hearts are uninspired."),
("myopic","GREEK ORIGIN",[("myein","to close, shut","閉上","a squinting eye"),("ops","eye, sight","眼睛","an eye")],("squinting eyes → nearsighted, thinking short-term","短視的；目光短淺的"),"a squinting boy grabs one candy right in front of him and doesn't see the giant treasure chest a few steps ahead.","Eyes half shut, he sees so near,","Myopic plans miss what is clear."),
("demonstrable","LATIN ORIGIN",[("de-","thoroughly, completely","完全地","a full progress bar"),("monstrare","to show","展示","a pointing hand at a screen")],("able to be fully shown → clearly provable","可證明的；明顯的"),"a student at a science fair drops a ball and a feather in a vacuum tube while a big screen shows the result and judges nod.","Show it, prove it, plain to see,","Demonstrable as can be."),
("callow","ENGLISH ORIGIN",[("calu","bare, bald, featherless (Old English)","光禿的；沒有羽毛的","a featherless baby bird"),("callow","unfledged → immature","未長羽毛 → 不成熟","a baby bird falling from a nest")],("without feathers yet → young and inexperienced","幼稚的；乳臭未乾的"),"a featherless baby bird in a tiny captain's hat tries to steer a big ship while wise old seabirds smile and shake their heads.","No feathers yet, so young and new,","A callow bird with much to do."),
]
